bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
docker exec "$cid" sh -c 'command -v ffmpeg >/dev/null && command -v ffprobe >/dev/null && test -w /tmp' || exit 62
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import pg from 'pg';import {readFileSync} from 'node:fs';
import {setDefaultResultOrder} from 'node:dns';import {setDefaultAutoSelectFamily} from 'node:net';
import {createCreatorTelegramFetch} from '/opt/videobot/src/runtime/creatorEgress.mjs';
import {createTelegramBotApi} from '/opt/videobot/src/telegram/botApi.mjs';
setDefaultResultOrder('ipv4first');setDefaultAutoSelectFamily(false);
const e=process.env,db=new pg.Pool({host:e.VIDEOBOT_DB_HOST,database:e.VIDEOBOT_DB_NAME,user:e.VIDEOBOT_DB_USER,password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:5000});
const tr=createCreatorTelegramFetch();
const api=createTelegramBotApi({token:readFileSync('/run/secrets/videobot_telegram_token','utf8').trim(),fetchImpl:tr.fetch,timeoutMs:25000});
try {
const q=await db.query("SELECT l.thumbnail_file_id,l.sample_file_id FROM videobot_post_receipts a JOIN videobot_listings l ON l.listing_id=a.listing_id WHERE a.paid_message_id=4691 AND a.free_message_ids=ARRAY[4689,4690]::bigint[]");
if(q.rowCount!==1)process.exitCode=70;
else{
 const item=q.rows[0];
 for(const ref of [item.thumbnail_file_id,item.sample_file_id]){
  const result=await api('getFile',{file_id:ref});
  if(!Number.isSafeInteger(result.file_size)||result.file_size<100||result.file_size>19000000)throw Error('MEDIA_SIZE_OUT_OF_ALLOWED_RANGE');
  if(typeof result.file_path!=='string'||!result.file_path.trim())throw Error('MEDIA_FILE_PATH_UNAVAILABLE');
 }
 console.log('ALBUM_TWO_ASSETS_AVAILABLE_FOR_SAFE_PRESENTATION=PASS');
}
}catch{process.exitCode=79}finally{await tr.close();await db.end();}
JS
